    /**
     * Method to retrieve the Issue via an IssuePrimaryKey.
     * @param 	id Long
     * @return 	Issue
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Issue handle( FindIssueQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getIssueId() );
    }
    
    /**
     * Method to retrieve a collection of all Issues
     *
     * @param	query	FindAllIssueQuery 
     * @return 	List<Issue> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Issue> handle( FindAllIssueQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindIssue,
 * but only if the id matches
 *
 * @param		entity	Issue
 */
	protected void emitFindIssue( Issue entity ) {
		LOGGER.info("handling emitFindIssue" );
		
	    queryUpdateEmitter.emit(FindIssueQuery.class,
	                            query -> query.getFilter().getIssueId().equals(entity.getIssueId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllIssue
	 * 
	 * @param		entity	Issue
	 */
	protected void emitFindAllIssue( Issue entity ) {
		LOGGER.info("handling emitFindAllIssue" );
		
	    queryUpdateEmitter.emit(FindAllIssueQuery.class,
	                            query -> true,
	                            entity);
	}

